// Package vibe embeds the licence files (LICENSE, NOTICE and the generated
// THIRD_PARTY_NOTICES.md, `task notices`) so the binaries can show them in
// Studio's Settings > About without reading from disk. It is the repository
// root's only package and has no other job.
package vibe

import _ "embed"

// License is the Apache-2.0 text of LICENSE.
//
//go:embed LICENSE
var License string

// Notice is NOTICE.
//
//go:embed NOTICE
var Notice string

// ThirdPartyNotices is THIRD_PARTY_NOTICES.md, generated by `task notices`.
//
//go:embed THIRD_PARTY_NOTICES.md
var ThirdPartyNotices string
